/// <summary>A bundled placeholder photo (Assets/Photos, generated by tools/gen-images.cs).</summary>
public sealed class Photo
{
    private static readonly Dictionary<int, Bitmap> Cache = new();

    public Photo(int index, string title, string location, DateOnly date)
    {
        Index = index;
        Title = title;
        Location = location;
        Date = date;
    }

    public int Index { get; }

    public string Title { get; }

    public string Location { get; }

    public DateOnly Date { get; }

    public string Caption => $"{Location} · {Date.ToString("MMMM yyyy", System.Globalization.CultureInfo.InvariantCulture)}";

    /// <summary>Decoded once per asset and shared by every page that shows it.</summary>
    public Bitmap Image
    {
        get
        {
            if (!Cache.TryGetValue(Index, out var bitmap))
            {
                using var stream = AssetLoader.Open(new Uri($"avares://AvaWin.Gallery/Assets/Photos/photo-{Index:00}.jpg"));
                Cache[Index] = bitmap = new Bitmap(stream);
            }

            return bitmap;
        }
    }

    public override string ToString() => Title;
}

/// <summary>A contact for the list demos: grouped by the first letter of the name.</summary>
public sealed class Contact
{
    public Contact(string firstName, string lastName, string city, Color color)
    {
        FirstName = firstName;
        LastName = lastName;
        City = city;
        Color = color;
        Brush = new SolidColorBrush(color);
    }

    public string FirstName { get; }

    public string LastName { get; }

    public string Name => FirstName + " " + LastName;

    public string City { get; }

    public string Email => $"{FirstName}.{LastName}@example.com".ToLowerInvariant();

    public string Initials => FirstName[..1] + LastName[..1];

    public string Group => FirstName[..1].ToUpperInvariant();

    public Color Color { get; }

    public IBrush Brush { get; }

    public override string ToString() => Name;
}

/// <summary>A group header item for grouped <see cref="ListView"/> demos and SemanticZoom's zoomed-out view.</summary>
public sealed class ContactGroup
{
    public required string Key { get; init; }

    public required int Count { get; init; }

    public string Title => Key;

    public override string ToString() => Key;
}

public sealed record Album(string Title, string Artist, Photo Cover, IReadOnlyList<Track> Tracks)
{
    public override string ToString() => Title;
}

public sealed record Track(int Number, string Title, string Duration);

public sealed record Article(string Section, string Title, string Summary, Photo Photo)
{
    public override string ToString() => Title;
}

