    /// <summary>An <see cref="ISupportIncrementalLoading"/> source that fabricates contact pages on demand.</summary>
    public sealed class IncrementalContacts : ObservableCollection<Contact>, ISupportIncrementalLoading
    {
        private readonly int _max;

        public IncrementalContacts(int initial, int max)
        {
            _max = max;
            foreach (var c in Enumerable.Range(0, initial).Select(Make))
            {
                Add(c);
            }
        }

        public int LoadCalls { get; private set; }

        public bool HasMoreItems => Count < _max;

        public async Task<int> LoadMoreItemsAsync(int count)
        {
            LoadCalls++;
            await Task.Delay(400);
            var start = Count;
            for (var i = 0; i < count && Count < _max; i++)
            {
                Add(Make(start + i));
            }

            return Count - start;
        }

        private static Contact Make(int i) => new(FirstNames[i % FirstNames.Length], LastNames[(i * 3) % LastNames.Length], Cities[i % Cities.Length], Palette[i % Palette.Length]);
    }

    private static IReadOnlyList<Track> Tracks(params string[] titles) =>
        titles.Select((t, i) => new Track(i + 1, t, $"{3 + (i * 7) % 3}:{(10 + i * 13) % 60:00}")).ToList();
}
